  static readonly DependencyProperty AccentRoleProperty=DependencyProperty.RegisterAttached("AccentRole",typeof(string),typeof(WidgetTheme),new PropertyMetadata(""));
  static readonly DependencyProperty TooltipHookProperty=DependencyProperty.RegisterAttached("TooltipHook",typeof(bool),typeof(WidgetTheme),new PropertyMetadata(false));
  public static double ClampScale(double value){return Double.IsNaN(value)||Double.IsInfinity(value)?1:Math.Max(.9,Math.Min(1.3,value));}
  public static void Install(FrameworkElement target){if((bool)target.GetValue(InstalledProperty))return;var dictionary=(ResourceDictionary)XamlReader.Parse(Templates);foreach(object key in dictionary.Keys)target.Resources[key]=dictionary[key];target.SetValue(InstalledProperty,true);}
  static SolidColorBrush Brush(string hex){return (SolidColorBrush)new BrushConverter().ConvertFromString(hex);}
  public static SolidColorBrush AccentBrush(string accent,bool pale=false){string solid="#759DFA",light="#AFC8FF";switch(accent){case "Green":solid="#6BC69D";light="#A0E0BD";break;case "Purple":solid="#B399F6";light="#D2C1FF";break;case "Amber":solid="#E5B567";light="#F1D49C";break;}return Brush(pale?light:solid);}
  static void Palette(FrameworkElement target,string accent){Install(target);target.Resources["Accent"]=AccentBrush(accent);target.Resources["AccentLight"]=AccentBrush(accent,true);}
  public static void Apply(Window window,Settings settings){Palette(window,settings.Accent);double scale=ClampScale(settings.TextScale);Capture(window,new HashSet<DependencyObject>());Visit(window,window,scale,new HashSet<DependencyObject>());if(window.ContextMenu!=null){Palette(window.ContextMenu,settings.Accent);window.ContextMenu.FontFamily=window.FontFamily;window.ContextMenu.FontSize=13*scale;Visit(window.ContextMenu,window,scale,new HashSet<DependencyObject>());foreach(var item in window.ContextMenu.Items){var menu=item as MenuItem;if(menu!=null)menu.FontSize=13*scale;}}}
  static void InstallTooltip(FrameworkElement element,FrameworkElement owner,double scale){
   element.SetValue(TooltipScaleProperty,scale);
   if((bool)element.GetValue(TooltipHookProperty))return;element.SetValue(TooltipHookProperty,true);
   element.ToolTipOpening+=(s,e)=>{if(!Object.ReferenceEquals(e.Source,element))return;var content=element.ToolTip;var tip=content as ToolTip;if(tip==null&&content is string){tip=new ToolTip{Content=content};element.ToolTip=tip;}if(tip==null)return;tip.Style=(Style)owner.Resources[typeof(ToolTip)];tip.FontFamily=owner is Window?((Window)owner).FontFamily:new FontFamily("Segoe UI");tip.FontSize=12*(double)element.GetValue(TooltipScaleProperty);};
  }
  static readonly DependencyProperty TooltipScaleProperty=DependencyProperty.RegisterAttached("TooltipScale",typeof(double),typeof(WidgetTheme),new PropertyMetadata(1d));
  // Capture inherited sizes before updating their parents, so labels do not scale twice.
  static void Capture(DependencyObject node,HashSet<DependencyObject> visited){if(node==null||!visited.Add(node))return;var text=node as TextBlock;var control=node as Control;if(Double.IsNaN((double)node.GetValue(BaselineProperty))){if(text!=null)node.SetValue(BaselineProperty,text.FontSize);else if(control!=null)node.SetValue(BaselineProperty,control.FontSize);}foreach(object child in LogicalTreeHelper.GetChildren(node)){var dependency=child as DependencyObject;if(dependency!=null)Capture(dependency,visited);}}
  static void Visit(DependencyObject node,FrameworkElement owner,double scale,HashSet<DependencyObject> visited){
   if(node==null||!visited.Add(node))return;var element=node as FrameworkElement;var text=node as TextBlock;var control=node as Control;
