    var border=node as Border;DependencyProperty prop=text!=null?TextBlock.ForegroundProperty:border!=null?Border.BackgroundProperty:control is ProgressBar?Control.ForegroundProperty:null;
    if(prop!=null){string role=(string)element.GetValue(AccentRoleProperty);var color=element.GetValue(prop) as SolidColorBrush;if(role.Length==0&&color!=null){string hex=color.Color.ToString();if(hex=="#FF759DFA")role="Accent";if(hex=="#FF89ABFF"||hex=="#FFAFC8FF")role="AccentLight";if(role.Length>0)element.SetValue(AccentRoleProperty,role);}if(role.Length>0)element.SetValue(prop,owner.Resources[role]);}
   }
   foreach(object child in LogicalTreeHelper.GetChildren(node)){var dependency=child as DependencyObject;if(dependency!=null)Visit(dependency,owner,scale,visited);}
  }
